    var ind_cd = $c.cp.valueOfIndex(cmb_ind_cd, "VALUE", cmb_ind_cd.getSelectedIndex());
    //var term = rd_term.CodeValue;

    var url = "/AdminAndDlstedDetection.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=getTransList&For=KNTCP&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_TCP" + "&ISU_CD=" + isu_cd + "&TASK_DD_S=" + task_dd_s + "&TASK_DD_E=" + task_dd_e + "&IND_CD=" + ind_cd;
    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();
    $c.cm.ShowWin(grd_List2); // 그리드명을 표기

};


/*
 * from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기   
 *  - 기간구분 : pTp
 *  - from 객체 이름 : pObjFrom
 *  - to 객체 이름 : pObjTo
 */
scwin.fn_setFromToDate = function(pTp, pObjFrom, pObjTo) {
    //1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    var vFrom = "";
    var vTo = $c.stf.getObjectValue(pObjTo);
    //alert(vTo);

    if (vTo == '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp == 0) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 0); // 하루(동일날짜)로		

    } else if (pTp == 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7); // 일주일전		

    } else if (pTp == 2) {
        // 1개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp == 3) {
        // 3개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp == 4) {
        // 6개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp == 5) {
        // 1년전
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp == 6) {
        // 2년전
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    }
    $c.stf.setObjectValue(pObjFrom, vFrom);
    $c.stf.setObjectValue(pObjTo, vTo);
};
scwin.fn_restrictDuration = function() {
    var duration = 6 * 31; //6개월
    var start = $c.stf.getObjectValue(edt_base_dt_1);
    var end = $c.stf.getObjectValue(edt_base_dt_2);
    var startDate = new Date();
    var endDate = new Date();
    startDate.setYear(start.substring(0, 4));
    startDate.setMonth(start.substring(4, 6));
    startDate.setDate(start.substring(6, 8));
    endDate.setYear(end.substring(0, 4));
    endDate.setMonth(end.substring(4, 6));
    endDate.setDate(end.substring(6, 8));
    var diffTime = endDate.getTime() - startDate.getTime();
    var diffDays = diffTime / (1000 * 60 * 60 * 24);
    if (diffDays > duration) {
        var msg = " 조회기간은 " + diffDays + "일로 " + duration + "일 이하로 제한됩니다.";
        $c.win.alert(msg);
        return false;
    }
    return true;
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List); //데이터 로딩중닫기 및 조회없음 처리		
    btn_Search.setDisabled(false);
    btn_Search.src = "../img/btn_select.gif";
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List2); //데이터 로딩중닫기 및 조회없음 처리		
