scwin.btn_Excel_onclick = function() {
    var tIndex = MxTab_1.getSelectedTabIndex();
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (tIndex == 1) {
        $c.data.downloadGridViewExcel(grd_List, "시가총액요건", "", "8");
    } else if (tIndex == 2) {
        $c.data.downloadGridViewExcel(grd_List2, "종류주식-시가총액요건", "", "8");
    }
};
scwin.btn_Search_onclick = function() {
    //DR 전환시 
    if (scwin.svrGubun == "dr") {
        $c.win.alert("DR에서 운영될때는 조회 서비스가 제공되지 않습니다.");
    } else {
        if (!scwin.fn_restrictDuration()) return; // 6개월 제한

        var tIndex = MxTab_1.getSelectedTabIndex();
        if (tIndex == 1) {
            scwin.fn_list_sync();
        } else if (tIndex == 2) {
            scwin.fn_list_sync_2();
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    var eCnt = 0; // 각 dataset 별 표시 count
    var tIndex = MxTab_1.getSelectedTabIndex();
    //alert(tIndex);
    if (tIndex == 1) {
        eCnt = dts_List.getTotalRow();
    } else if (tIndex == 2) {
        eCnt = dts_List2.getTotalRow();
    }
    $c.stf.FillGridHeaderTotalCnt(eCnt, panel_page);
    //tab을 선택 시 기존 그리드의 '조회결과 없음'표시를 닫는다.
    if ($c.frame.path("NoData") != null) {
        await $c.frame.CloseFrame();
    }
};
scwin.txb_ISU_CD_onkeyup = function() {
    if (txb_ISU_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISU_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISU_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISU_CD.getValue() == "") {
        txb_ISU_NM.setValue("");
    }
};
scwin.img_ISU_NM_onclick = function() {
    $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST + ' ' + SECUGRP_ID_RT + ' ' + SECUGRP_ID_DR + ' ' + SECUGRP_ID_FS, js_market, "A");
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.gform_onload = function() {
    MxTab_1.setSelectedTabIndex(1);
    //round처리
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_SetCode();

    //오늘날짜로 초기화시킨다.
    var y_day = $c.ud.fn_get_search_taskdd(dts_TASK_DD, 'H');
    $c.stf.setObjectValue(edt_base_dt_1, y_day);
    $c.stf.setObjectValue(edt_base_dt_2, y_day);
    $c.cm.fn_com_isur(txb_ISU_CD, txb_ISU_NM);
    Grd_com_isur.style.zIndex = 30;
};
